actions.action:
// Physical presence but below threshold - no Commerce Tax due
result.nv_qualifies_for_exemption = true;
result.nv_commerce_tax = 0.0;
apportionment.state_tax = 0.0;

// No nexus - no filing required
result.nv_qualifies_for_exemption = true;
result.nv_commerce_tax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Nevada has NO corporate income tax
            // Set income tax rate to zero
            apportionment.state_tax_rate = 0.0;

            // No state additions or subtractions (no income tax base)
            apportionment.state_additions = 0.0;
            apportionment.state_subtractions = 0.0;

// No nexus - confirm zero tax
apportionment.state_tax_rate = 0.0;
apportionment.state_additions = 0.0;
apportionment.state_subtractions = 0.0;

            // Calculate Nevada-sitused gross revenue using market-based sourcing
            result.nv_sitused_revenue =
              revenue.total_revenue * apportionment.apportionment_percentage;

            // Gross revenue includes sitused revenue (same for Commerce Tax)
            result.nv_gross_revenue = result.nv_sitused_revenue;

// No apportionment calculated - assume 100% Nevada if nexus exists
result.nv_sitused_revenue = revenue.total_revenue;
result.nv_gross_revenue = revenue.total_revenue;

            // Calculate taxable revenue (gross revenue minus $4M threshold)
            result.nv_taxable_revenue = Math.max(0.0,
              result.nv_gross_revenue - result.nv_commerce_tax_threshold);

            // Calculate Commerce Tax on taxable revenue
            result.nv_commerce_tax = result.nv_taxable_revenue * result.nv_commerce_tax_rate;

            // Apply credits
            result.nv_commerce_tax = Math.max(0.0,
              result.nv_commerce_tax - apportionment.state_credits);

            // Nevada Commerce Tax is reported as "state tax" for consistency with framework
            // Note: This is NOT an income tax
            apportionment.state_tax = result.nv_commerce_tax;

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

// Below threshold - no Commerce Tax
result.nv_qualifies_for_exemption = true;
result.nv_taxable_revenue = 0.0;
result.nv_commerce_tax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

// No nexus - no Commerce Tax
result.nv_qualifies_for_exemption = true;
result.nv_taxable_revenue = 0.0;
result.nv_commerce_tax = 0.0;
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;
